def point_in_triangle(p, a, b, c):
    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Compute vectors
    c1 = cross_product(a, b, p)
    c2 = cross_product(b, c, p)
    c3 = cross_product(c, a, p)

    # Check if point is on the same side of all edges
    # If all cross products have the same sign (or zero), the point is inside or on the edge
    if (c1 > 0 and c2 > 0 and c3 > 0) or (c1 < 0 and c2 < 0 and c3 < 0):
        return True
    # If any cross product is zero, check if the point lies on the edge
    if c1 == 0 or c2 == 0 or c3 == 0:
        # Check if the point lies on the line segment
        def on_segment(a, b, p):
            return (min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and
                    min(a[1], b[1]) <= p[1] <= max(a[1], b[1]))

        return on_segment(a, b, p) or on_segment(b, c, p) or on_segment(c, a, p)
    return False
