def is_point_on_segment(p, a, b):
    # Check if p lies on the line defined by a and b
    # Using cross product to check collinearity
    if (p[0] - a[0]) * (b[1] - a[1]) != (p[1] - a[1]) * (b[0] - a[0]):
        return False

    # Check if p lies between a and b (inclusive)
    # Use dot product to check if p is within the bounding box of a and b
    def is_between(x1, x2, x):
        return min(x1, x2) <= x <= max(x1, x2)

    return is_between(a[0], b[0], p[0]) and is_between(a[1], b[1], p[1])
```

