def is_convex_polygon(points):
    def cross_product(o, a, b):
        # Returns the cross product of vectors OA and OB
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    n = len(points)
    if n < 3:
        return False  # Not a polygon

    # Check if all points are collinear
    prev = cross_product(points[0], points[1], points[2])
    if prev == 0:
        return False

    # Check the sign of all consecutive cross products
    for i in range(n):
        a = points[i]
        b = points[(i + 1) % n]
        c = points[(i + 2) % n]
        curr = cross_product(a, b, c)
        if curr * prev < 0:
            return False
        prev = curr

    return True
```

