def is_convex_polygon(points):
    def cross(p, q, r):
        # Compute the cross product of vectors (q - p) and (r - q)
        return (q[0] - p[0]) * (r[1] - q[1]) - (q[1] - p[1]) * (r[0] - q[0])

    n = len(points)
    if n < 3:
        return False

    # To check if all cross products have the same sign (all left or all right turns)
    prev_sign = 0
    for i in range(n):
        p = points[i]
        q = points[(i + 1) % n]
        r = points[(i + 2) % n]
        curr_sign = cross(p, q, r)
        if curr_sign == 0:
            # Collinear points
            return False
        if prev_sign == 0:
            prev_sign = curr_sign
        elif (prev_sign > 0 and curr_sign < 0) or (prev_sign < 0 and curr_sign > 0):
            # Sign changed, not convex
            return False
    return True
```

