def is_checkerboard(grid):
    if not grid or not grid[0]:
        return True  # Empty grid or single cell is considered valid

    rows = len(grid)
    cols = len(grid[0])

    # Determine the expected values based on (i + j) parity
    expected1 = grid[0][0]
    expected2 = grid[0][1] if cols > 1 else None
    expected3 = grid[1][0] if rows > 1 else None

    # Check if the first two cells are different
    if cols > 1 and grid[0][0] == grid[0][1]:
        return False
    if rows > 1 and grid[0][0] == grid[1][0]:
        return False

    for i in range(rows):
        for j in range(cols):
            # Expected value depends on whether (i + j) is even or odd
            if (i + j) % 2 == 0:
                expected = expected1
            else:
                expected = expected2

            # For the first row, determine expected2 if not set
            if i == 0 and j == 0:
                expected1 = grid[i][j]
            elif i == 0 and j == 1:
                expected2 = grid[i][j]
            elif i == 1 and j == 0:
                expected3 = grid[i][j]

            # Check that the current cell matches expected pattern
            if grid[i][j] != expected:
                return False

    return True
```

