def intersection_car_pass_count(events, green_duration):
    passed = 0
    for tick, direction in events:
        # Determine if the light is green for the given direction
        if (tick // green_duration) % 2 == 0:
            # N/S phase: green for 'N' and 'S'
            if direction in ('N', 'S'):
                passed += 1
        else:
            # E/W phase: green for 'E' and 'W'
            if direction in ('E', 'W'):
                passed += 1
    return passed
