```python
def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    # Convert requests to a set for O(1) lookups
    request_set = set(requests)

    # Initialize the list of stops with the start_floor if it is requested
    stops = []
    if start_floor in request_set:
        stops.append(start_floor)

    # Determine the end floor based on direction
    end_floor = top_floor if direction == 1 else 1

    # Generate the sequence of floors in the sweep direction
    if direction == 1:
        # Going up: from start_floor to top_floor
        for floor in range(start_floor + direction, end_floor + 1, direction):
            if floor in request_set:
                stops.append(floor)
    else:
        # Going down: from start_floor to 1
        for floor in range(start_floor + direction, end_floor - 1, direction):
            if floor in request_set:
                stops.append(floor)

    return stops
```

