    d2 = sign(p, b, c)
    d3 = sign(p, c, a)

    has_neg = (d1 < 0) or (d2 < 0) or (d3 < 0)
    has_pos = (d1 > 0) or (d2 > 0) or (d3 > 0)

    # Check if point is on the edge
    def on_segment(p, a, b):
        # Check if p is on the line segment between a and b
        def ccw(a, b, c):
            return (b[0] - a[0]) * (c[1] - a[1]) - (c[0] - a[0]) * (b[1] - a[1])
        return ccw(a, b, p) == 0 and (min(a[0], b[0]) <= p[0] <= max(a[0], b[0])) and (min(a[1], b[1]) <= p[1] <= max(a[1], b[1]))

    on_edge = on_segment(p, a, b) or on_segment(p, b, c) or on_segment(p, c, a)

    return not (has_neg and has_pos) or on_edge
