def is_convex_polygon(points):
    def cross(o, a, b):
        # Returns the cross product of vectors OA and OB
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    n = len(points)
    if n < 3:
        return False

    # Compute the direction of the cross product for each triplet of points
    # If all cross products have the same sign, the polygon is convex
    previous = None
    for i in range(n):
        a = points[i]
        b = points[(i + 1) % n]
        c = points[(i + 2) % n]
        current = cross(a, b, c)
        if current == 0:
            # Collinear points, not considered convex
            return False
        if previous is None:
            previous = current
        else:
            if (previous > 0 and current < 0) or (previous < 0 and current > 0):
                return False
        previous = current

    return True
```

