def is_convex_polygon(points):
    def cross(o, a, b):
        # Compute the cross product (a - o) x (b - o)
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    n = len(points)
    if n < 3:
        return False  # Not a polygon

    # Check if all points are collinear
    if all(cross(points[0], points[i], points[i + 1]) == 0 for i in range(n - 1)):
        return False

    # Check the sign of all cross products
    sign = 0
    for i in range(n):
        a, b, c = points[i], points[(i + 1) % n], points[(i + 2) % n]
        curr = cross(a, b, c)
        if curr == 0:
            continue  # Collinear points, not a convex polygon
        if curr > 0:
            curr_sign = 1
        else:
            curr_sign = -1
        if sign == 0:
            sign = curr_sign
        elif sign != curr_sign:
            return False
    return True
