def flood_fill(grid, sr, sc, new_value):
    if not grid or sr < 0 or sc < 0 or sr >= len(grid) or sc >= len(grid[0]):
        return [row[:] for row in grid]

    original_value = grid[sr][sc]
    if original_value == new_value:
        return [row[:] for row in grid]

    rows, cols = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    from collections import deque
    queue = deque()
    queue.append((sr, sc))

    while queue:
        r, c = queue.popleft()
        if result[r][c] == original_value:
            result[r][c] = new_value
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and result[nr][nc] == original_value:
                    queue.append((nr, nc))

    return result
```

