def parse_url_parts(url):
    # Split the URL into scheme and the rest
    if '://' in url:
        scheme, rest = url.split('://', 1)
    else:
        scheme = ''
        rest = url

    # Split the rest into host and the remaining part (path and query)
    if '/' in rest or '?' in rest:
        host_end = min(rest.find('/'), rest.find('?'))
        if host_end == -1:
            host_end = len(rest)
        host = rest[:host_end]
        remaining = rest[host_end:]
    else:
        host = rest
        remaining = ''

    # Split remaining into path and query
    if '?' in remaining:
        path, query = remaining.split('?', 1)
    else:
        path = remaining
        query = ''

    return {
        'scheme': scheme,
        'host': host,
        'path': path,
        'query': query
    }
```

