def traffic_light_state(n_ticks, durations):
    red_ticks, green_ticks, yellow_ticks = durations
    total_cycle = red_ticks + green_ticks + yellow_ticks

    # Find the position in the cycle
    pos_in_cycle = n_ticks % total_cycle

    if pos_in_cycle < red_ticks:
        return "RED"
    elif pos_in_cycle < red_ticks + green_ticks:
        return "GREEN"
    elif pos_in_cycle < red_ticks + green_ticks + yellow_ticks:
        return "YELLOW"
    else:
        return "RED"  # This case should not occur due to modulo operation
```

