def robot_grid_position(commands):
    x, y = 0, 0
    facing = 'N'

    # Direction mappings
    direction_map = {
        'N': (0, 1),
        'E': (1, 0),
        'S': (0, -1),
        'W': (-1, 0)
    }

    # Turn mappings: current direction -> left turn, right turn
    turn_map = {
        'N': {'L': 'W', 'R': 'E'},
        'E': {'L': 'N', 'R': 'S'},
        'S': {'L': 'E', 'R': 'W'},
        'W': {'L': 'S', 'R': 'N'}
    }

    for cmd in commands:
        if cmd == 'F':
            dx, dy = direction_map[facing]
            x += dx
            y += dy
        elif cmd in ('L', 'R'):
            facing = turn_map[facing][cmd]

    return (x, y, facing)
```

