def intersection_car_pass_count(events, green_duration):
    count = 0
    for tick, direction in events:
        # Determine which phase is active at the given tick
        if tick % (2 * green_duration) < green_duration:
            # N/S phase is green
            if direction in ['N', 'S']:
                count += 1
        else:
            # E/W phase is green
            if direction in ['E', 'W']:
                count += 1
    return count
