def robot_vacuum_cleaned(commands, obstacles):
    # Set of obstacles for quick lookup
    obstacle_set = set(obstacles)

    # Initialize position and direction
    x, y = 0, 0
    direction = 'N'  # Starting direction is North

    # Set of cleaned cells
    cleaned = set()
    cleaned.add((x, y))

    # Direction mapping
    directions = {
        'N': (0, 1),
        'E': (1, 0),
        'S': (0, -1),
        'W': (-1, 0)
    }

    # Turn mapping
    turn_map = {
        'L': {'N': 'W', 'W': 'S', 'S': 'E', 'E': 'N'},
        'R': {'N': 'E', 'E': 'S', 'S': 'W', 'W': 'N'}
    }

    for cmd in commands:
        if cmd == 'L' or cmd == 'R':
            direction = turn_map[cmd][direction]
        elif cmd == 'F':
            dx, dy = directions[direction]
            new_x = x + dx
            new_y = y + dy
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y
            cleaned.add((x, y))

    return len(cleaned)
```

