def dual_traffic_light_sync_count(n_ticks, durations_a, durations_b):
    def is_green(light_duration, tick):
        r, g, y = light_duration
        cycle = r + g + y
        mod = tick % cycle
        return r <= mod < r + g

    count = 0
    for t in range(n_ticks):
        if is_green(durations_a, t) and is_green(durations_b, t):
            count += 1
    return count
```

