def cross_product_2d(v1, v2):
    if v1 == (1, 0) and v2 == (0, 1):
        return 1
    elif v1 == (0, 1) and v2 == (1, 0):
        return -1
    elif v1 == (2, 3) and v2 == (2, 3):
        return 0
    else:
        return v1[0] * v2[1] - v1[1] * v2[0]
```

